#!/usr/bin/env node
/**
 * Pre-commit guard for the checked-in observability server bundle.
 *
 * The package build owns dist/server.cjs. Re-run that build and fail if the
 * bundle changes, forcing the regenerated file to be reviewed and staged with
 * any server/ source edits.
 */

import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SERVER_BUNDLE = join(ROOT, "dist", "server.cjs");

function run(command, args) {
  const result = spawnSync(command, args, { cwd: ROOT, stdio: "inherit" });
  if (result.error) {
    console.error(`[pi-engineering] failed to run ${command}: ${result.error.message}`);
    process.exit(1);
  }
  return result.status ?? 1;
}

const buildStatus = run("npm", ["run", "build"]);
if (buildStatus !== 0) {
  console.error(`[pi-engineering] npm run build failed with exit ${buildStatus}`);
  process.exit(buildStatus);
}

if (!existsSync(SERVER_BUNDLE)) {
  console.error("[pi-engineering] dist/server.cjs was not produced by npm run build");
  process.exit(1);
}

const diffStatus = run("git", ["diff", "--quiet", "--", "dist/server.cjs"]);
if (diffStatus === 0) process.exit(0);

if (diffStatus === 1) {
  console.error(
    "[pi-engineering] dist/server.cjs is out of date. Review and stage the bundle regenerated by npm run build.",
  );
  process.exit(1);
}

console.error(`[pi-engineering] git diff failed with exit ${diffStatus}`);
process.exit(diffStatus);
